import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import React, { Component } from "react";
import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";
import { changePage } from "../../actions/pageActions";
import {
  Checkbox,
  Snackbar,
  Paper,
  Tab,
  Tabs,
  Box,
  MenuItem,
  Breadcrumbs,
  Link,
  Select,
  Button,
  FormHelperText,
  FormControl,
  InputLabel,
  Grid,
  Typography
} from "@material-ui/core";
import { makeStyles } from "@material-ui/core/styles";
import InfoIcon from "@material-ui/icons/Info";
import AddIcon from "@material-ui/icons/Add";
class ProcessGroupDetail extends Component {
  state = {
    value: 0
  };
  onPageChangeClick = (navType, page, objId) => {
    const pageDetail = {
      navType,
      page,
      objId
    };
    this.props.changePage(pageDetail);
  };
  handleChange = (event, newValue) => {
    this.setState({ value: newValue });
  };

  render() {
    function renderPageSwitch(index) {
      switch (index) {
        case 1:
          return "Process UI 1";
        case 2:
          return "Process UI 2";
        case 3:
          return "Process UI 3";

        default:
          return "Undefined Tab Index";
      }
    }
    return (
      <Grid container>
        <Grid item sm sm={12}>
          <Paper style={{ padding: 20, margin: 10 }}>
            <Breadcrumbs
              style={{
                display: "flex",
                justifyContent: "center"
              }}
            >
              <Link
                onClick={this.onPageChangeClick.bind(
                  this,
                  "MainNav",
                  "ProcessGroups",
                  0
                )}
                href="#"
              >
                Process Groups
              </Link>

              <Typography color="textPrimary">Process Group Details</Typography>
            </Breadcrumbs>
          </Paper>
          <Paper style={{ padding: 10, margin: 10 }}>
            <Grid container>
              <Grid item sm sm={4}>
                <div title="Process groups are 1 or more processes.  Each processes uses item(s) and outputs item(s). Use process groups to group processes in any way you want. Some recommended ways of grouping are the following: 1. group processes that sequentially use the output item of the last process 2. Group proceses that are for one product 3. Place assembly processes in a standalone process group 4. place any process in a process group by itself if you like.  Really this tool is made for your own organization such as a file structure.">
                  <h4>
                    {""}
                    <InfoIcon /> Process Group Name: Ball Nut Production
                  </h4>
                  <p>Process Group ID:{this.props.id}</p>
                </div>
              </Grid>

              <Grid item sm sm={4}>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "center"
                  }}
                >
                  <div title="Please select processes to add to the below process group.  This will add the process to this group for organization purposes.  Each process utilizes item(s) and generates item(s)">
                    <InfoIcon />{" "}
                    <FormControl style={{ minWidth: 200 }}>
                      <InputLabel id="demo-simple-select-helper-label">
                        Choose Process
                      </InputLabel>
                      <Select labelId="demo-simple-select-helper-label">
                        <MenuItem value={1}>Machining</MenuItem>
                        <MenuItem value={2}>Assembly</MenuItem>
                        <MenuItem value={3}>CMM Validation</MenuItem>
                        <MenuItem value={4}>Visual Validation</MenuItem>
                      </Select>
                    </FormControl>{" "}
                    <Button>
                      <AddIcon />
                    </Button>
                  </div>
                </div>
              </Grid>

              <Grid item sm sm={4}></Grid>
            </Grid>
          </Paper>
        </Grid>
        <Grid item sm={2}>
          <Paper style={{ padding: 20, margin: 10 }}>
            <Tabs
              orientation="vertical"
              variant="scrollable"
              value={this.state.value}
              onChange={this.handleChange}
            >
              <Tab label="Machining" value={1} />
              <Tab label="Assembly" value={2} />
              <Tab label="Visual Validation" value={3} />
            </Tabs>
          </Paper>
        </Grid>
        <Grid item sm sm={10}>
          <Paper style={{ padding: 20, margin: 10 }}>
            Process ID: askldflajsdfl; created by: User
          </Paper>
          <Paper style={{ padding: 20, margin: 10 }}>
            {renderPageSwitch(this.state.value)}
          </Paper>
        </Grid>
      </Grid>
    );
  }
}

const mapStateToProps = state => ({
  auth: state.auth
});

export default connect(mapStateToProps, { changePage })(ProcessGroupDetail);
